create table xxcus.xxfnd_entity_containers (
    entity_container_id   number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    entity_name           varchar2(60 byte) not null enable,
    pk1_value             varchar2(150 byte) not null enable,
    storage_config_id     number not null enable,
    external_folder_id    varchar2(500 byte),
    external_folder_path  varchar2(2000 byte) not null enable,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxfnd_entity_containers
    add constraint xxfnd_entity_containers_pk primary key ( entity_container_id )
        using index enable;

alter table xxcus.xxfnd_entity_containers
    add constraint xxfnd_entity_containers_uk1
        unique ( entity_name,
                 pk1_value,
                 storage_config_id )
            using index enable;


